class Solution {
    public boolean hasGroupsSizeX(int[] deck){
        Map<Integer,Integer> frequency=new HashMap<>();
        for(int card:deck)frequency.merge(card,1,Integer::sum);
        int divisor=0;
        for(int count:frequency.values())divisor=gcd(divisor,count);
        return divisor>=2;
    }
    private int gcd(int a,int b){
        while(b!=0){
            int temporary=a%b;
            a=b;
            b=temporary;
        }
        return a;
    }
}

code.kotlin:
class Solution {
    fun hasGroupsSizeX(deck:IntArray):Boolean{
        val frequency=deck.toList().groupingBy{
            it
        }.eachCount();
        var divisor=0;
        for(count in frequency.values)divisor=gcd(divisor,count);
        return divisor>=2
    };
    private fun gcd(aInput:Int,bInput:Int):Int{
        var a=aInput;
        var b=bInput;
        while(b!=0){
            val temporary=a%b;
            a=b;
            b=temporary
        };
        return a
    }
}

code.cpp:
class Solution {
    public: bool hasGroupsSizeX(vector<int>& deck){
        unordered_map<int,int> frequency;
        for(int card:deck)++frequency[card];
        int divisor=0;
        for(auto [card,count]:frequency)divisor=gcd(divisor,count);
        return divisor>=2;
    }
};
